Translate the following MS C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <cstdio>
#include <cassert>
#include <functional>
#include <iostream>

using namespace std;

int main() {
#ifndef ONLINE_JUDGE
    assert(freopen("input.txt", "r", stdin));
    assert(freopen("output.txt", "w", stdout));
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    function<long long(long long)> calc;
    calc = [&](long long n) -> long long {
        if (n == 0) return 0;
        long long r = 0;
        int d = 0;
        while (r * 10 + 1 <= n) {
            r = r * 10 + 1;
            ++d;
        }
        long long first = d * (n / r) + calc(n % r);
        long long x = 10 * r + 1 - n;
        long long second = d + 1 + d * (x / r) + calc(x % r);
        return first < second ? first : second;
    };

    long long n;
    cin >> n;
    cout << calc(n);
    return 0;
}
</original_code>
